class Reader {
  public:
    explicit Reader(std::span<const std::uint8_t> bytes) : bytes_(bytes) {}

    std::uint8_t byte() {
        if (cursor_ >= bytes_.size()) {
            throw std::logic_error("Truncated algorithm parameters");
        }
        return bytes_[cursor_++];
    }

    std::uint32_t word() {
        std::uint32_t result = 0;
        for (int index = 0; index < 4; ++index) {
            result = (result << 8) | byte();
        }
        return result;
    }

    template <std::size_t Size> void read(std::array<std::uint8_t, Size>& output) {
        if (Size > bytes_.size() - cursor_) {
            throw std::logic_error("Truncated algorithm parameters");
        }
        std::copy_n(bytes_.begin() + cursor_, Size, output.begin());
        cursor_ += Size;
    }

  private:
    std::span<const std::uint8_t> bytes_;
    std::size_t cursor_ = 0;
};

ProvisioningResponseKeyParameters response_key(Reader& input) {
    ProvisioningResponseKeyParameters result{};
    for (auto& codec : result.input_matrix_codecs) {
        codec.offset = input.byte();
        input.read(codec.basis_offset);
        for (auto& column : codec.columns) {
            column.source_byte = input.byte();
            column.row_mask = input.byte();
            input.read(column.column_map.basis);
        }
    }
    for (auto& map : result.encoded_key_maps) {
        input.read(map.basis);
    }
    for (auto& map : result.decoded_key_maps) {
        input.read(map.basis);
    }
    input.read(result.round_key_masks);
    return result;
}

const ProvisioningRequestParameters& request() {
    static const auto result = [] {
        Reader input(request_data);
        ProvisioningRequestParameters value{};
        input.read(value.selector.key);
        input.read(value.selector.iv);
        input.read(value.selector.input_mask);
        input.read(value.hardware);
        input.read(value.response.response.spim.key);
        input.read(value.response.response.spim.iv);
        value.response.response.key = response_key(input);
        input.read(value.response.response.hash_suffix);
        input.read(value.response.digest_key);
        return value;
    }();
    return result;
}

ProvisioningSelectorSourceParameters selector_source() {
    Reader input(std::span<const std::uint8_t>(request_data).subspan(988));
    ProvisioningSelectorSourceParameters result{};
    input.read(result.key);
    input.read(result.iv);
    return result;
}

const ProvisioningEndPacketParameters& end() {
    static const auto result = [] {
        Reader input(end_data);
        ProvisioningEndPacketParameters value{};
        input.read(value.payload.spim.key);
        input.read(value.payload.spim.iv);
        value.payload.response_key = response_key(input);
        input.read(value.payload.key_derivation_key);
        input.read(value.authentication_key);
        return value;
    }();
    return result;
}

const StateGsaParameters& state() {
    static const auto result = [] {
        Reader input(state_data);
        StateGsaParameters value{};
        input.read(value.body_key.program_key);
        input.read(value.body_key.input_whitening);
        input.read(value.body_key.output_whitening);
        input.read(value.schema.field_mask);
        value.schema.outer_tag = input.word();
        for (auto& tag : value.schema.record_tags) {
            tag = input.word();
        }
        input.read(value.seed_cipher.key);
        input.read(value.seed_cipher.iv);
        auto& cipher = value.key.secondary_cipher;
        input.read(cipher.key);
        input.read(cipher.iv);
        input.read(cipher.whitening);
        for (auto& map : cipher.output_maps) {
            input.read(map.basis);
        }
        auto& key = value.key.mixed_key;
        for (auto& source : key.sources) {
            input.read(source);
        }
        input.read(key.offsets);
        input.read(key.mapped_sources.basis);
        return value;
    }();
    return result;
}

const StateStoreParameters& store() {
    static const auto result = [] {
        const auto& common = state();
        StateStoreParameters value{};
        value.body_key = common.body_key;
        value.schema = common.schema;
        value.seed_cipher = common.seed_cipher;
        Reader input(store_data);
        input.read(value.secondary_cipher.key);
        input.read(value.secondary_cipher.iv);
        input.read(value.secondary_cipher.whitening);
        for (auto& map : value.secondary_cipher.output_maps) {
            input.read(map.basis);
        }
        return value;
    }();
    return result;
}

